// Complete replacement code for n8n node: Generate Jobs Email HTML

const report = $input.first().json || {};
const jobs = Array.isArray(report.jobs) ? report.jobs : [];
if (jobs.length === 0) throw new Error('Refusing to generate a selected-jobs email with zero jobs.');
const reportLimit = Number(report.report_limit);
if (!Number.isInteger(reportLimit) || reportLimit < 1) {
  throw new Error('Selected-jobs report has an invalid report_limit.');
}
if (jobs.length > reportLimit) {
  throw new Error(`Selected-jobs report contains ${jobs.length} jobs for a limit of ${reportLimit}.`);
}

const required = ['job_id', 'position', 'company_name', 'joburl'];
for (const [index, job] of jobs.entries()) {
  const missing = required.filter((key) => job?.[key] == null || String(job[key]).trim() === '');
  if (missing.length) throw new Error(`Job ${index} is missing required fields: ${missing.join(', ')}`);
}

function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}
function display(value, fallback = 'Not available') {
  const normalized = String(value ?? '').trim();
  return esc(normalized || fallback);
}
function safeLinkedInUrl(value) {
  const raw = String(value || '').trim();
  if (!raw || /[\u0000-\u0020\u007f]/.test(raw)) return null;
  const match = raw.match(/^https:\/\/([^/?#]+)(\/[^?#]*)?(?:\?[^#]*)?(?:#.*)?$/i);
  if (!match) return null;
  const authority = match[1].toLowerCase();
  if (authority.includes('@')) return null;
  const host = authority.replace(/:443$/, '');
  if (host !== 'linkedin.com' && !host.endsWith('.linkedin.com')) return null;
  return raw;
}
function listHtml(value, fallback) {
  const entries = String(value ?? '')
    .split('[END_OF_BULLET]')
    .map((entry) => entry.trim())
    .filter(Boolean);
  if (entries.length === 0) return `<li>${esc(fallback)}</li>`;
  return entries.map((entry) => `<li>${esc(entry)}</li>`).join('');
}
function dimBadge(value) {
  if (value === null || value === undefined || value === 'null' || value === '') {
    return '<span class="dim-score dim-null" title="Not available">—</span>';
  }
  const number = Number(value);
  if (!Number.isFinite(number)) return '<span class="dim-score dim-null" title="Not available">—</span>';
  const cls = number >= 4 ? 'dim-high' : number >= 3 ? 'dim-mid' : 'dim-low';
  return `<span class="dim-score ${cls}" title="Score ${esc(number)} out of 5">${esc(number)}</span>`;
}

const counts = report.counts || {};
const failures = Array.isArray(report.failed_jobs) ? report.failed_jobs : [];
const visibleFailures = failures.slice(0, 20);
const failureItems = visibleFailures.map((failure) => {
  const url = safeLinkedInUrl(failure.job_url);
  const label = display(failure.title || failure.job_id, 'LinkedIn job');
  const link = url ? `<a href="${esc(url)}">${label}</a>` : label;
  return `<li>${link} — ${display(failure.summary, 'Automated analysis failed after retries.')}</li>`;
}).join('');
const hiddenFailureCount = Math.max(0, failures.length - visibleFailures.length);

const cards = jobs.map((job) => {
  const url = safeLinkedInUrl(job.joburl);
  if (!url) throw new Error(`Job ${job.job_id} has an invalid LinkedIn URL.`);
  return `<article class="card">
    <div class="card-header">
      <h2>${display(job.position)} at ${display(job.company_name)}</h2>
      <a href="${esc(url)}" class="button">View job posting</a>
    </div>
    <div class="job-info">
      <span><strong>Job ID:</strong> ${display(job.job_id)}</span>
      <span><strong>Location:</strong> ${display(job.location)}</span>
      <span><strong>Salary:</strong> ${display(job.salary)}</span>
      <span><strong>Posted:</strong> ${display(job.posted_date)}</span>
      <span><strong>Policy:</strong> ${display(job.analysis_details?.policy_version)}</span>
      <span><strong>Travel:</strong> ${display(job.analysis_details?.travel?.status === "quantified" ? ` ${job.analysis_details.travel.mandatory === false ? "Optional" : job.analysis_details.travel.mandatory === true ? "Required" : "Necessity unclear"}: up to ${job.analysis_details.travel.annual_trips_max} trips/year` : job.analysis_details?.travel?.status === "not_stated" ? "Not stated (not a rejection)" : "Needs verification")}</span>
    </div>
    <table class="ratings-table">
      <caption>Fit ratings</caption>
      <thead><tr><th scope="col">Overall</th><th scope="col">Preference</th><th scope="col">Skill</th><th scope="col">Explanation</th></tr></thead>
      <tbody><tr><td>${display(job.overall_rating)}</td><td>${display(job.preferences_rating)}</td><td>${display(job.skill_rating)}</td><td>${display(job.evaluation)}</td></tr></tbody>
    </table>
    <table class="dim-table">
      <caption>Dimension ratings</caption>
      <thead><tr><th scope="col">Employee satisfaction</th><th scope="col">Salary</th><th scope="col">Remote flexibility</th><th scope="col">Skills alignment</th><th scope="col">Cultural fit</th></tr></thead>
      <tbody><tr><td>${dimBadge(job.dim_employee_satisfaction)}</td><td>${dimBadge(job.dim_salary_competitiveness)}</td><td>${dimBadge(job.dim_remote_work_flexibility)}</td><td>${dimBadge(job.dim_skills_alignment)}</td><td>${dimBadge(job.dim_cultural_fit)}</td></tr></tbody>
    </table>
    <section><h3>Preference matches</h3><ul>${listHtml(job.preference_matches, 'No preference matches')}</ul></section>
    <section><h3>References</h3><ul>${listHtml(job.preference_references, 'No preference references')}</ul></section>
    <section><h3>Preference misses</h3><ul>${listHtml(job.preference_misses, 'No preference misses')}</ul></section>
    <section><h3>Potential preference matches</h3><ul>${listHtml(job.potential_preference_matches, 'No potential preference matches')}</ul></section>
    <section><h3>Skill matches</h3><ul>${listHtml(job.skill_matches, 'No skill matches')}</ul></section>
    <section><h3>Skill misses</h3><ul>${listHtml(job.skill_misses, 'No skill misses')}</ul></section>
    <section><h3>Transferable skills</h3><ul>${listHtml(job.skill_translations, 'No transferable skills')}</ul></section>
  </article>`;
}).join('');

const omittedNotice = Number(counts.omitted_by_limit || 0) > 0
  ? `<p><strong>${esc(counts.omitted_by_limit)} additional qualifying job(s)</strong> were not included because this report is capped at ${esc(reportLimit)} current-run jobs.</p>`
  : '';
const databaseWarning = Number(counts.database_missing || 0) > 0
  ? `<p><strong>Warning:</strong> ${esc(counts.database_missing)} selected job(s) could not be read back from the database.</p>`
  : '';
const failureSection = failures.length > 0
  ? `<section class="review"><h2>Jobs requiring manual review (${esc(failures.length)})</h2><p>Automated analysis failed after three attempts. These jobs were not scored or selected automatically.</p><ul>${failureItems}</ul>${hiddenFailureCount ? `<p>${esc(hiddenFailureCount)} additional failure(s) are available in the execution record.</p>` : ''}</section>`
  : '';

const held = Array.isArray(report.review_jobs) ? report.review_jobs : [];
const heldItems = held.slice(0,20).map(item=>{const url=safeLinkedInUrl(item.job_url);const label=esc(item.title || item.job_id);return `<li>${url ? `<a href="${esc(url)}">${label}</a>` : label} — ${esc(item.summary)}</li>`;}).join('');
const heldSection = held.length ? `<section class="review"><h2>Eligibility or evidence verification (${esc(held.length)})</h2><p>Not automatically selected; these are unresolved conditions, not proven bad fits.</p><ul>${heldItems}</ul></section>` : '';
const reasonCounts = Object.entries(report.rejection_reason_counts || {}).map(([code,count])=>`${esc(code)}: ${esc(count)}`).join('; ');
const reasonSection = reasonCounts ? `<section><h2>Decision reasons</h2><p>${reasonCounts}</p></section>` : '';

const html = `<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Current Job Search Report</title>
<style>
body{font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;background:#f4f7fa;color:#111827;line-height:1.6;margin:0;padding:20px}.container{max-width:1100px;margin:0 auto;background:#fff;border-radius:12px;padding:24px}h1{text-align:center;font-size:26px}h2{font-size:19px}h3{font-size:16px}.summary,.review{border:1px solid #94a3b8;border-radius:10px;padding:16px;margin:20px 0}.card{border:2px solid #64748b;border-radius:10px;padding:16px;margin:20px 0;background:#f8fafc}.card-header{display:flex;justify-content:space-between;align-items:center;gap:16px}.button{display:inline-block;padding:10px 14px;min-height:24px;background:#1d4ed8;color:#fff!important;text-decoration:none;border-radius:6px;font-weight:700}.job-info{display:grid;grid-template-columns:1fr 1fr;gap:8px 16px;margin-bottom:16px}table{width:100%;border-collapse:collapse;margin:16px 0}caption{text-align:left;font-weight:700;margin-bottom:6px}th,td{padding:8px;text-align:left;border-bottom:1px solid #cbd5e1}.dim-table{table-layout:fixed}.dim-table th{overflow-wrap:anywhere}.dim-table th,.dim-table td{text-align:center}.dim-score{display:inline-block;min-width:28px;height:28px;line-height:28px;border-radius:50%;font-weight:700;color:#fff}.dim-high{background:#166534}.dim-mid{background:#92400e}.dim-low{background:#991b1b}.dim-null{background:#475569}a{color:#1d4ed8}ul{padding-left:22px}@media(max-width:650px){body{padding:8px}.container{padding:14px}.card-header{display:block}.button{margin-top:8px}.job-info{grid-template-columns:1fr}th,td{font-size:12px;padding:5px}}
</style></head><body><main class="container"><h1>Current Job Search Report</h1>
<section class="summary"><h2>Run summary</h2><p>${esc(counts.feed || 0)} feed item(s) → ${esc(counts.distinct || 0)} distinct job(s) → ${esc(counts.new || 0)} new job(s) → ${esc(counts.selected || 0)} selected, ${esc(counts.rejected || 0)} rejected, ${esc(counts.held || 0)} held for verification, ${esc(counts.failed || 0)} failed.</p>${omittedNotice}${databaseWarning}</section>
${cards}${heldSection}${failureSection}${reasonSection}</main></body></html>`;

return [{ json: { ...report, output: html, subject: `Job Search Report — ${jobs.length} current match${jobs.length === 1 ? '' : 'es'}` } }];

const ledger = $('Build Run Ledger').first().json;
const selectedIds = new Set((ledger.selected_job_ids || []).map((value) => String(value)));
const rows = $input.all()
  .map((item) => item.json || {})
  .filter((row) => /^\d{6,20}$/.test(String(row.job_id || '')))
  .filter((row) => selectedIds.has(String(row.job_id)));

const returnedIds = new Set(rows.map((row) => String(row.job_id)));
if (returnedIds.size !== rows.length) {
  throw new Error('Current-run database query returned duplicate job IDs.');
}

const resultLimit = Number(ledger.report_limit);
if (!Number.isInteger(resultLimit) || resultLimit < 1) {
  throw new Error('Build Run Ledger returned an invalid report_limit.');
}
if (rows.length > resultLimit) {
  throw new Error(`Current-run database query returned ${rows.length} rows for a report limit of ${resultLimit}.`);
}
const expectedRowsWithinLimit = Math.min(selectedIds.size, resultLimit);
const databaseMissing = Math.max(0, expectedRowsWithinLimit - rows.length);
const omittedByLimit = Math.max(0, selectedIds.size - resultLimit);
const reportState = rows.length > 0
  ? (databaseMissing > 0 ? 'selected_jobs_with_warnings' : 'selected_jobs')
  : (selectedIds.size > 0 ? 'report_incomplete' : 'no_qualifying_jobs');

return [{
  json: {
    ...ledger,
    report_state: reportState,
    jobs: rows.map(row=>({...row, analysis_details:ledger.selected_details?.[String(row.job_id)] || null})),
    counts: {
      ...(ledger.counts || {}),
      emailed: rows.length,
      omitted_by_limit: omittedByLimit,
      database_missing: databaseMissing,
    },
  },
}];

'use strict';

// Shared, dependency-free policy embedded verbatim into the exported Code nodes.
// Treat model output as data. Source-excerpt checks establish provenance, not semantic truth.
const FIT_DIMENSIONS = ['employee_satisfaction', 'salary_competitiveness', 'remote_work_flexibility', 'skills_alignment', 'cultural_fit'];
const FIT_WEIGHTS = Object.freeze({skills_alignment: 60, salary_competitiveness: 15, remote_work_flexibility: 10, cultural_fit: 10, employee_satisfaction: 5});
function fitObject(value) { return value !== null && typeof value === 'object' && !Array.isArray(value); }
function fitExact(value, keys, label) {
  if (!fitObject(value) || Object.keys(value).length !== keys.length || keys.some(key => !Object.prototype.hasOwnProperty.call(value, key))) throw new Error(`${label}: invalid fields.`);
}
function fitText(value, max, label) {
  if (typeof value !== 'string' || !value.trim() || value.length > max) throw new Error(`${label}: invalid text.`);
}
function fitEnum(value, allowed, label) { if (!allowed.includes(value)) throw new Error(`${label}: invalid enum.`); }
function fitNumber(value, min, max, label, integer = false) {
  if (typeof value !== 'number' || !Number.isFinite(value) || value < min || value > max || (integer && !Number.isInteger(value))) throw new Error(`${label}: invalid number.`);
}
function fitReadPolicy(envelope) {
  const p = envelope.policy;
  fitExact(p, ['version','target_amount','target_currency','target_basis','required_work_arrangement','max_annual_trips','minimum_skill_rating','score_threshold','resume_sha256'], 'policy');
  fitText(p.version, 80, 'policy.version');
  fitNumber(p.target_amount, 1000, 999999999, 'policy.target_amount', true);
  if (typeof p.target_currency !== 'string' || !/^[A-Z]{3}$/.test(p.target_currency)) throw new Error('Invalid target currency.');
  fitEnum(p.target_basis, ['base','total_compensation'], 'policy.target_basis');
  fitEnum(p.required_work_arrangement, ['fully_remote','hybrid','on_site','any'], 'policy.required_work_arrangement');
  fitNumber(p.max_annual_trips, 0, 365, 'policy.max_annual_trips', true);
  fitNumber(p.minimum_skill_rating, 1, 5, 'policy.minimum_skill_rating', true);
  fitNumber(p.score_threshold, 1, 5, 'policy.score_threshold');
  if (typeof p.resume_sha256 !== 'string' || !/^[a-f0-9]{64}$/.test(p.resume_sha256)) throw new Error('Invalid resume digest.');
  return p;
}
function fitNormalize(value) { return String(value || '').replace(/\s+/g, ' ').trim(); }
// Keep only bounded fields that are supplied verbatim to the model and evidence validator.
// Oversized research text is omitted, not silently treated as a complete source.
function fitNormalizeResearch(source) {
  source = source && typeof source === 'object' && !Array.isArray(source) ? source : {};
  const rawAnswer = typeof source.answer === 'string' ? source.answer : '';
  const results = [];
  let limited = rawAnswer.length > 8000;
  for (const row of (Array.isArray(source.results) ? source.results : []).slice(0, 5)) {
    if (!row || typeof row !== 'object' || Array.isArray(row)) { limited = true; continue; }
    const url = typeof row.url === 'string' ? row.url.trim() : '';
    const authority = url.split('/')[2] || '';
    if (!/^https?:\/\//i.test(url) || url.length > 2048 || /[\x00-\x20\x7f]/.test(url) || !authority || authority.includes('@')) { limited = true; continue; }
    const title = typeof row.title === 'string' ? row.title : '';
    const content = typeof row.content === 'string' ? row.content : '';
    const omitted = content.length > 20000;
    limited ||= omitted || title.length > 500;
    results.push({url, title:title.slice(0, 500), content:omitted ? '' : content, content_omitted:omitted, title_truncated:title.length > 500, published_date:typeof row.published_date === 'string' ? row.published_date.slice(0, 50) : ''});
  }
  return {answer:rawAnswer.length > 8000 ? '' : rawAnswer, answer_omitted:rawAnswer.length > 8000, results, limited_data:limited, error:source.error ? 'Research unavailable.' : null};
}

function fitPostingText(envelope) { return String(envelope.job?.content || '').trim() || String(envelope.job?.contentSnippet || '').trim(); }
function fitSourceMap(envelope) {
  const map = new Map();
  const url = String(envelope.job?.link || envelope.job?.job_url || '').replace(/\/$/, '');
  if (url) map.set(url, [envelope.job?.title, envelope.job?.location, fitPostingText(envelope)].filter(Boolean).map(fitNormalize));
  for (const source of (envelope.research?.results || []).slice(0, 5)) {
    if (typeof source.url === 'string' && typeof source.content === 'string') {
      const key = source.url.replace(/\/$/, '');
      map.set(key, [...(map.get(key) || []), ...[source.title,source.content].filter(Boolean).map(fitNormalize)]);
    }
  }
  return map;
}
function fitEvidence(records, envelope, label, required = true) {
  if (!Array.isArray(records) || records.length > 5 || (required && records.length === 0)) throw new Error(`${label}: missing or excessive source evidence.`);
  const sources = fitSourceMap(envelope);
  for (const record of records) {
    fitExact(record, ['source_url','quote'], label);
    fitText(record.source_url, 2048, `${label}.source_url`);
    fitText(record.quote, 1500, `${label}.quote`);
    const source = sources.get(record.source_url.replace(/\/$/, ''));
    if (!source || !source.some(chunk => chunk.includes(fitNormalize(record.quote)))) throw new Error(`${label}: excerpt is not present in the supplied source.`);
  }
}
function fitEligibility(preferences, policy) {
