const source = $('Process Job Postings').item.json;
const response = $input.first().json || {};
const url = `https://www.linkedin.com/jobs/view/${source.job_id}`;
const result = Array.isArray(response.results) ? response.results.find(r => r && r.url === url && typeof r.raw_content === 'string' && r.raw_content.trim()) : null;
const text = result ? result.raw_content.trim() : String(source.content || '').trim() || String(source.contentSnippet || '').trim();
// Do not silently truncate missing qualifications into apparent matches.
const oversized = text.length > 200000;
return [{json:{...source, title:String(source.title || '').slice(0,240), location:String(source.location || '').slice(0,1000), content: oversized ? '' : text, contentSnippet: oversized ? '' : source.contentSnippet,
  posting_retrieval: {status: oversized ? 'oversized' : result ? 'retrieved' : 'feed_fallback', source_url: url, extraction_failed: !result, assessment_required: true}}}];
